public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;
    for (String str : strings) {
        if (str.length() > maxLength) {
            maxLength = str.length();
        }
    }

    for (int size = maxLength; size >= 1; size--) {
        List<String> sublists = new ArrayList<>();
        for (int i = 0; i <= strings.size() - size; i++) {
            List<String> subset = new ArrayList<>(strings.subList(i, i + size));
            sublists.add(String.join("", subset));
        }

        for (String sub : sublists) {
            if (strings.contains(sub) || strings.contains(sub.reverse().toString())) {
                return size;
            }
        }
    }

    return 0;
}

