public static int findLargestSubstring(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be null or empty.");
        }

        String largest = "";
        for (String s : strings) {
            String reverseS = new StringBuilder(s).reverse().toString();
            if (s.contains(largest) || reverseS.contains(largest)) {
                if (s.length() > reverseS.length()) {
                    largest = s;
                } else if (s.length() < reverseS.length()) {
                    largest = reverseS;
                } else {
                    largest = s; // In case of a tie, choose the lexicographically smaller string first
                }
            }
        }
        return largest.length();
    }

