public double trimMean(int[] arr) {
    // Sort the array
    Arrays.sort(arr);

    // Calculate the number of elements to trim
    int trimSize = arr.length * 5 / 100;

    // Sum the trimmed elements
    int sum = 0;
    for (int i = trimSize; i < arr.length - trimSize; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    return (double) sum / (arr.length - (2 * trimSize));
}

