public double trimMean(int[] arr) {
    // Calculate the sorted ArrayList from the array
    List<Double> sortedList = Arrays.stream(arr).boxed().collect(Collectors.toList());

    // Sort the ArrayList in ascending order
    sortedList.sort(Comparator.naturalOrder());

    int numElements = sortedList.size();

    // Calculate the number of elements to trim from the start and end
    int trimSize = (int) (0.05 * numElements);

    // Trim the first and last 'trimSize' elements
    sortedList.subList(0, trimSize).clear();
    sortedList.subList(numElements - trimSize, numElements).clear();

    // Add the remaining elements
    double sum = sortedList.stream().mapToDouble(Double::doubleValue).sum();

    // Calculate the mean and return with an error of 10^-5
    return Math.round(sum * 100000) / 100000.0;
}

