public String sortString(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        char[] array = s.toCharArray();
        int start = 0, end = array.length - 1;
        String result = "";

        while (true) {
            if (start > end) {
                break;
            }
            if (result.isEmpty() || array[start] <= result.charAt(result.length() - 1)) {
                result += array[start++];
            } else if (result.isEmpty() || array[end] >= result.charAt(result.length() - 1)) {
                result += array[end--];
            }
        }

        return result;
    }

