public String sortString(String s) {
    char[] chars = s.toCharArray();
    int[] count = new int[26];

    for (char c : chars) {
        count[c - 'a']++;
    }

    StringBuilder res = new StringBuilder();
    int index = 0;

    while (index < chars.length) {
        // Pick smallest character
        if (count[index] > 0) {
            res.append((char) ('a' + index));
            count[index]--;
        }
        index++;
        // Pick largest character
        if (count[25 - index] > 0) {
            res.append((char) ('a' + (25 - index)));
            count[25 - index]--;
        }
        index++;
    }

    return res.toString();
}

