public static boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length < 2) {
            return false;
        }

        int totalSum = Arrays.stream(nums).sum();
        int targetSum = totalSum / 2;

        boolean[] dp = new boolean[targetSum + 1];
        dp[0] = true;

        for (int num : nums) {
            for (int i = targetSum; i >= num; i--) {
                dp[i] = dp[i] || dp[i - num];
            }
        }

        return dp[targetSum];
    }

