public int maxUniqueSplit(String s) {
    if (s == null || s.length() <= 1) {
        return s.length();
    }

    Set<String> uniqueSubstrings = new HashSet<>();
    int maxUnique = 0;

    for (int i = 1; i <= s.length(); i++) {
        String sub = s.substring(0, i);
        if (uniqueSubstrings.contains(sub)) {
            continue;
        }

        uniqueSubstrings.add(sub);
        maxUnique++;

        for (int j = i + 1; j <= s.length(); j++) {
            String nextSub = s.substring(i, j);
            if (uniqueSubstrings.contains(nextSub)) {
                break;
            }

            uniqueSubstrings.add(nextSub);
            maxUnique++;
        }
    }

    return maxUnique;
}

