public String getSmallestString(int n, int k) {
    int[] alpha = new int[26];
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < 26; i++) {
        while (k - (i + 1) >= 0) {
            k -= (i + 1);
            alpha[i]++;
        }
    }

    for (int i = 25; i >= 0; i--) {
        if (alpha[i] > 0) {
            while (alpha[i]-- > 0) {
                sb.append((char) ('a' + i));
            }
            break;
        }
    }

