    // If the number is 0, it's already a single digit
    if (num == 0) {
        return 0;
    }

    // Calculate the sum of digits
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }

    // Recursively call addDigits on the sum until a single digit is obtained
    return addDigits(sum);
}

