public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] dp = new int[4]; // dp[0] - horizontal, dp[1] - vertical, dp[2] - diagonal, dp[3] - anti-diagonal

    int maxLength = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Update the length of the current line in each direction:
                dp[0] = (j > 0) ? dp[0] + 1 : 1;
                dp[1] = (i > 0) ? dp[1] + 1 : 1;
                dp[2] = (i > 0 && j > 0) ? dp[2] + 1 : 1;
                dp[3] = (i < rows - 1 && j < cols - 1) ? dp[3] + 1 : 1;

                maxLength = Math.max(maxLength, Math.max(Math.max(dp[0], dp[1]), Math.max(dp[2], dp[3])));
            } else {
                // Reset the direction arrays for the next line:
                Arrays.fill(dp, 0);
            }
        }
    }

    return maxLength;
}

