public static String addThousandSeparator(int n) {
        StringBuilder sb = new StringBuilder();
        int count = 0;
        while (n > 0) {
            count++;
            int digit = n % 10;
            if (count % 3 == 0 && count != 0) {
                sb.append('.');
            }
            sb.append(digit);
            n /= 10;
        }
        if (sb.length() > 0 && sb.charAt(0) == '.') {
            sb.deleteCharAt(0);
        }
        return sb.reverse().toString();
    }

