public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int m = mat[0].length;
    int[][] dirs = { {1, 0}, {0, 1} }; // Directions: right, down
    int totalElements = n * m;
    int[] result = new int[totalElements];
    int cur = 0;
    int r = 0, c = 0; // Current row and column indices

    while (cur < totalElements) {
        result[cur++] = mat[r][c];
        int nextRow = r + dirs[cur%2][0];
        int nextCol = c + dirs[cur%2][1];

        // If next row or column is out of bounds or repeated, go back
        if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= m || (r == nextRow && c == nextCol)) {
            r -= dirs[cur%2][0]; // Backtrack to previous row and column
            c -= dirs[cur%2][1];
            cur++;
        }
        if (cur == totalElements) break;
        r = nextRow;
        c = nextCol;
    }

    return result;
}

