public static int findNthUglyNumber(int n) {
    Set<Integer> uglyNumbers = new HashSet<>();
    PriorityQueue<Long> priorityQueue = new PriorityQueue<>();
    uglyNumbers.add(1L);
    PriorityQueue<Long> minHeap = new PriorityQueue<>();
    minHeap.offer(2L);
    minHeap.offer(3L);
    minHeap.offer(5L);

    while (n-- > 0) {
        long currentUgly = priorityQueue.poll();
        while (!minHeap.isEmpty() && minHeap.peek() <= currentUgly) {
            long nextUgly = minHeap.poll();
            uglyNumbers.add(nextUgly);
            priorityQueue.offer(nextUgly * 2);
            priorityQueue.offer(nextUgly * 3);
            priorityQueue.offer(nextUgly * 5);
        }
    }

    return uglyNumbers.stream().findFirst().getAsInt();
}

