    int start = 0, end = 0;

    for (int i = 0; i <= chars.length; i++) {
        if (i == chars.length || chars[i] == ' ') {
            while (start < end) {
                output[start] = chars[end - 1];
                start++;
                end--;
            }
            output[start] = chars[i];
            start = end = i + 1;
        }
    }

    return new String(output);
}

